package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** A dated setting is recorded from its from-date, else from the sheet's today. */
public class SaveSettings {
    public void save(@Val SettingsChange change, Settings settings, Sheets sheets) {
        String sheetId = change.sheetId();
        LocalDate today = sheets.today(sheetId);
        if (change.setsClerkLimit()) setDated(settings, change, today, Settings.CLERK_LIMIT, change.clerkLimit());
        if (change.floor() != null) setDated(settings, change, today, Settings.FLOOR, change.floor());
        if (change.terms() != null) setDated(settings, change, today, Settings.TERMS, BigDecimal.valueOf(change.terms()));
        change.gradeTerms().forEach((grade, terms) -> setDated(settings, change, today, Settings.gradeKey(grade),
                terms != null ? BigDecimal.valueOf(terms) : null));
        if (change.latePct() != null) setDated(settings, change, today, Settings.LATE_PCT, change.latePct());
        if (change.setsPolicyDate()) settings.setPolicyDate(sheetId, change.policyDate());
        if (change.setsCap()) setDated(settings, change, today, Settings.CAP, change.cap());
        if (change.setsProofThreshold()) setDated(settings, change, today, Settings.PROOF_THRESHOLD, change.proofThreshold());
        if (change.setsPeriodNumberingFrom()) settings.setPeriodNumberingFrom(sheetId, change.periodNumberingFrom());
    }

    private static void setDated(Settings settings, SettingsChange change, LocalDate today, String key, BigDecimal value) {
        settings.setDated(change.sheetId(), key, change.froms().getOrDefault(key, today), value);
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A validated settings change on a sheet: whether the clerk limit is set and to what (null for no
 *  limit), the floor, the terms and the late percent, each null when it is not being set, and
 *  whether the policy date is set and to what (null for blank: the sheet's today), and whether the period numbering from is set and to what (null for blank: off), and the terms set per grade, by grade (a null value clears the grade's own terms, so it uses the sheet's), and whether the cap is set and to what (null for no cap), and the from-date given for a dated setting, by its key (clerk-limit, floor, terms, terms-<grade>, late-pct, cap; one not in it is from the sheet's today), and whether the proof threshold is set and to what (null for none). */
public record SettingsChange(String sheetId, boolean setsClerkLimit, BigDecimal clerkLimit, BigDecimal floor, Integer terms, BigDecimal latePct, boolean setsPolicyDate, LocalDate policyDate, boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String by, boolean setsCap, BigDecimal cap, Map<String, LocalDate> froms, boolean setsProofThreshold, BigDecimal proofThreshold) {
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.jdbc.core.JdbcTemplate;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Repository;

/** Each sheet's settings: the roles given to user names, its policy date, its period numbering from,
 *  and its dated settings — its clerk limit, its floor, its terms (and any per grade), its late percent
 *  its cap and its proof threshold — each recorded from from-dates. */
@Repository
public class Settings {

    /** The floor of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms, in days, of a sheet that has not set them. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The keys of the dated settings. */
    public static final String CLERK_LIMIT = "clerk-limit", FLOOR = "floor", TERMS = "terms",
            LATE_PCT = "late-pct", CAP = "cap",
            PROOF_THRESHOLD = "proof-threshold";

    private final JdbcTemplate jdbc;
    private final Sheets sheets;

    public Settings(JdbcTemplate jdbc, Sheets sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** The user's role on the sheet: a clerk unless given another. */
    public Role role(String sheetId, String user) {
