     *  of its figure for every full 30 days overdue. 0.00 before any is recorded. */
    public BigDecimal latePct(String sheetId, LocalDate date) {
        return valueOn(sheetId, LATE_PCT, date, DEFAULT_LATE_PCT);
    }

