package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import java.math.BigDecimal;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim its number (see {@link ClaimNumbers}); a voided claim keeps it (and it is never reused).
 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
 *  bound it to, else its person's grade's rate in force on the claim's date, at least the sheet's floor, plus its late charge then; with no rate it stays live. The user who opened a claim may not settle it.
 *  When a clerk settles a claim whose due is over the sheet's clerk limit (a due of n/a is within any
 *  limit) it goes PENDING instead, its due still live; a steward settles anything. Only a steward
 *  approves a PENDING claim (it settles, its due fixed at its live figure then, plus its late charge),
 *  and never the user who opened it; a rejection sends it back to OPEN, bound again by the last
 *  statement if that bound it.
 *  A claim whose due is above the sheet's proof threshold in force on its date cannot be settled or
 *  approved while it has no proofs (refused before the clerk limit is considered).
 *  A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
 *  A claim dated in a closed period cannot change status at all. */
public class ApplyClaimStatus {
    public void apply(@Val ClaimStatusChange change, @Val Claim claim, ClaimNumbers numbers, People people,
            Figures figures, ClosedPeriods closedPeriods, Settings settings)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        if (!change.action().allowedFrom(claim.getStatus())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
        }
        if (change.action() == ClaimAction.SETTLE && claim.isDeferred()) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        if (change.action() == ClaimAction.SETTLE && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(change.user())) {
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (change.action() == ClaimAction.APPROVE) {
            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
            }
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
                throw new ClaimStatusRefusedException("Only a steward can approve a pending claim");
            }
        }
        BigDecimal due = null;
        boolean pending = false;
        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            // Figures.figure: the bound figure for an OPEN claim, the live one for a PENDING claim.
            due = figures.figure(claim, grade);
            if (due != null) due = due.add(figures.charge(claim, due));
            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), claim.getDate());
            if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
            }
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK;
        }
        claim.setStatus(pending ? ClaimStatus.PENDING : change.action().to());
        if (change.action() == ClaimAction.OPEN) {
            claim.setNumber(numbers.next(claim));
            claim.setOpenedBy(change.user());
        }
        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
            claim.setDue(due);
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Reopens a closed period, making its due-total live again. Only a steward may reopen a period,
 *  and only a closed one can be reopened. Publishes the reopened period. */
public class ReopenPeriod {
    public void reopen(@Val Period period, @Val PeriodCloseRequest request, Periods periods, Settings settings,
            Out<ReopenedPeriod> reopened) throws PeriodClosedException {
        if (settings.role(period.sheetId(), request.user()) != Role.STEWARD) {
            throw new PeriodClosedException("Only a steward can reopen period " + period.name());
        }
        if (!period.closed()) throw new PeriodClosedException("Period " + period.name() + " is not closed");
        periods.reopen(period);
        reopened.set(new ReopenedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to())));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes the period, fixing its due-total as the screen shows it now: the figures (as shown now) of
 *  everyone's claims dated in it that were counted (OPEN, PENDING or SETTLED) by the status each had
 *  at the end of the period's last day, as its status log records it — not deferred ones, nor
 *  ones open then and dated within their person's hold, unless stated — n/a ones skipped. A closed period cannot be
 *  closed again. Each person's due-total for it is fixed too, and the
 *  period's is their sum. Publishes the closed period. */
public class ClosePeriod {
    public void close(@Val Period period, Periods periods, Claims claims, People people, Figures figures, ClaimLog log,
            Out<ClosedPeriod> closed) throws PeriodClosedException {
        if (period.closed()) throw new PeriodClosedException("Period " + period.name() + " is already closed");
        Map<Long, Person> personOf = people.onSheet(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Long id : personOf.keySet()) personTotals.put(id, BigDecimal.ZERO.setScale(2));
        Map<Long, ClaimStatus> atEnd = log.statusesAt(period.sheetId(), period.to());
        for (Claim claim : claims.onSheet(period.sheetId())) {
            if (!period.contains(claim.getDate())) continue;
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim,
                    atEnd.containsKey(claim.getId()) ? atEnd.get(claim.getId()) : claim.getStatus())) continue;
            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
            if (figure != null) personTotals.merge(person.getId(), figure, BigDecimal::add);
        }
        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        periods.close(period, total, personTotals);
        closed.set(new ClosedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total)));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;

/** Moves a DRAFT, OPEN or PENDING claim to another person on the sheet; only a steward may. The
 *  claim keeps its number and date but loses any figure a statement bound it to: it is live again
 *  until its new person's next statement. A SETTLED or VOID claim cannot move, nor a claim dated in
 *  a closed period, nor one dated after its new person's retirement date. */
public class ApplyClaimReassign {
    public void apply(@Val ClaimReassignment change, @Val Claim claim, People people, Settings settings,
            ClosedPeriods closedPeriods)
            throws ClaimStatusRefusedException, PersonNotFoundException, PersonRetiredException, PeriodClosedException {
        if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
            throw new ClaimStatusRefusedException("Only a steward can reassign a claim");
        }
        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
            throw new ClaimStatusRefusedException("A " + claim.getStatus() + " claim cannot be reassigned");
        }
        Person to = people.find(claim.getSheetId(), change.toPersonId());
        if (to == null) throw new PersonNotFoundException(change.toPersonId());
        if (to.getId() == claim.getPersonId()) {
            throw new ClaimStatusRefusedException("The claim is already " + to.getName() + "'s: reassign it to another person");
        }
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        to.refuseRetired(claim.getDate());
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        change.moved(from.getName(), to.getName());
        claim.setPersonId(to.getId());
        claim.setStated(false);
        claim.setStatedDue(null);
    }
}
